      menu.addItem((item) => item.setTitle(tr("Insertar fila debajo")).setIcon("arrow-down-to-line").onClick(() => this.insertTableRow(table2, row2 + 1)));
      menu.addItem((item) => item.setTitle(tr("Insertar columna a la izquierda")).setIcon("arrow-left-to-line").onClick(() => this.insertTableColumn(table2, col)));
      menu.addItem((item) => item.setTitle(tr("Insertar columna a la derecha")).setIcon("arrow-right-to-line").onClick(() => this.insertTableColumn(table2, col + 1)));
