    el.style.top = `${tb.y}px`;
    el.style.transform = tb.rotation ? `rotate(${tb.rotation}deg)` : tb.stickyColor ? `rotate(var(--sticky-tilt, 0deg))` : "";
    el.contentEditable = "false";
    el.setAttr("role", "textbox");
